def main():
    assert set(P.keys()) == set(IDS), (set(IDS) - set(P.keys()))
    os.makedirs(OUT, exist_ok=True)
    written = []
    for cid in IDS:
        d = P[cid]
        rec = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
               "confidence": d["confidence"], "trigger": d["trigger"]}
        assert set(rec.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}, cid
        assert isinstance(rec["confidence"], (int, float)) and 0.0 <= rec["confidence"] <= 1.0, cid
        tg = rec["trigger"]
        assert set(tg.keys()) == {"changed_main","reserve_used","disputed","reason"}, cid
        assert all(isinstance(tg[k], bool) for k in ("changed_main","reserve_used","disputed")), cid
        assert isinstance(tg["reason"], str), cid
        path = os.path.join(OUT, cid + ".json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=2)
        written.append(path)
    # verify each written file round-trips and id set matches exactly this batch
    for cid in IDS:
        with open(os.path.join(OUT, cid + ".json"), encoding="utf-8") as f:
            r = json.load(f)
        assert r["case_id"] == cid and len(r) == 5, cid
    cm = sum(1 for c in IDS if P[c]["trigger"]["changed_main"])
    ru = sum(1 for c in IDS if P[c]["trigger"]["reserve_used"])
    di = sum(1 for c in IDS if P[c]["trigger"]["disputed"])
    print(f"WROTE {len(written)} files; changed_main={cm} reserve_used={ru} disputed={di}")

if __name__ == "__main__":
    main()
